package com.example.aymobiledigitallibrary.ui.components
import androidx.compose.foundation.BorderStroke;import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp
@Composable fun SelectableCard(title:String,desc:String,selected:Boolean,onClick:()->Unit){OutlinedCard(Modifier.fillMaxWidth().clickable{onClick()},colors=CardDefaults.outlinedCardColors(containerColor=if(selected) MaterialTheme.colorScheme.surfaceColorAtElevation(2.dp) else MaterialTheme.colorScheme.surface),border=BorderStroke(1.dp,if(selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline)){Column(Modifier.padding(16.dp)){Text(title,fontWeight=FontWeight.SemiBold);Text(desc)}}}
